INSERT INTO jd_sections (code,title,body,sort,status) VALUES ('about','关于金鼎盛典','{"lead": "金鼎盛典是面向影视院校毕业生与青年创作者的年度作品盛典，以“发现新一代影视创作力量”为使命，联动迭影计划的算力扶持、迭代影市的版权交易与发行中心的全渠道发行，形成“发现—孵化—交易—发行”的完整链路。", "points": ["面向：影视院校毕业生、青年导演、AI 专业电影团队", "定位：人才与作品的发现节点，而非唯一入口", "原则：评奖、投决、采购三条决策线相互独立；获奖不等于获投或发行承诺"]}',0,'草案');
INSERT INTO jd_sections (code,title,body,sort,status) VALUES ('system','体系架构','{"items": [["金鼎盛典", "年度作品盛典：征集、评审、颁奖、展映", "发现"], ["迭影计划", "5,000 万元 AI 影视算力扶持、导师孵化", "孵化"], ["迭代影市", "剧本 / IP、联合开发、成片许可挂牌交易", "交易"], ["发行中心", "国内平台与海外发行、报表对账与分账", "发行"]]}',1,'草案');
INSERT INTO jd_sections (code,title,body,sort,status) VALUES ('tracks','赛道与奖项','{"tracks": [["完成作品组", "完整审片版、梗概、主创名单、权利声明、AI 使用说明", ["最佳叙事作品", "最佳动画作品", "最佳视觉表达"]], ["项目提案组", "大纲、人物小传、美术概念图、两支 30—60 秒概念片、预算与算力估算", ["年度潜力项目", "最佳项目提案"]]], "weights": {"完成作品组": "叙事 40 · 美学 25 · 技术完成度 20 · 创新 15", "项目提案组": "故事 30 · 技术可行性 25 · 市场 20 · 团队 15 · 预算 10"}}',2,'草案');
INSERT INTO jd_sections (code,title,body,sort,status) VALUES ('review','评审机制','{"steps": [["资格初筛", "资料完整性与权利链审查，版权争议、材料造假一票暂停"], ["双专家盲审", "每部作品至少 2 名无利益冲突专家独立评分；分差 ≥20 分加第三位专家复核"], ["利益回避", "师生、同团队、近期商业合作等关系须申报并回避"], ["双人审批发布", "获奖结果由运营提名 + 另一人批准后发布，可撤销、可追溯"], ["申诉", "结果送达后 5 个工作日内可就程序、事实或利益冲突提出申诉"]]}',3,'草案');
INSERT INTO jd_sections (code,title,body,sort,status) VALUES ('calendar','年度日历','{"items": [["征集", "每年 10 月 — 次年 2 月"], ["初评与辅导", "3 月 — 4 月"], ["入围公布", "5 月"], ["盛典与展映", "6 月：颁奖典礼、优秀作品展映、项目路演、版权洽谈、海外发行交流"], ["会后履约", "7 月起：签约项目进入孵化与发行"]]}',4,'草案');
INSERT INTO jd_sections (code,title,body,sort,status) VALUES ('honor','荣誉与证书','{"lead": "每个奖项生成唯一电子证书编号，可在平台“证书验真”公开查验；获奖作品自动进入荣誉库，并可获得迭影计划荣誉加成算力。"}',5,'草案');
